def max_value_on_paths(N: int, grid_values: list[tuple[int, int, int]]) -> int:
    # Build grid with 1-based indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # Edge case: 1x1 grid
    if N == 1:
        return grid[1][1]

    # DP arrays: use -inf for impossible states
    NEG_INF = -10**18
    prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    prev[1][1] = grid[1][1]

    # Steps: sum of coordinates ranges from 2 to 2N
    for step in range(3, 2 * N + 1):
        cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        # i1 and i2 range from 1 to N, compute corresponding j's
        for i1 in range(1, N + 1):
            j1 = step - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(1, N + 1):
                j2 = step - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG_INF
                # Transition candidates
                # both moved down
                if i1 > 1 and i2 > 1:
                    best = max(best, prev[i1 - 1][i2 - 1])
                # first down, second right
                if i1 > 1 and j2 > 1:
                    best = max(best, prev[i1 - 1][i2])
                # first right, second down
                if j1 > 1 and i2 > 1:
                    best = max(best, prev[i1][i2 - 1])
                # both right
                if j1 > 1 and j2 > 1:
                    best = max(best, prev[i1][i2])
                if best == NEG_INF:
                    continue
                add_val = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add_val += grid[i2][j2]
                cur[i1][i2] = best + add_val
        prev = cur

    return prev[N][N]

def max_value_on_paths(N: int, grid_values) -> int:
    """
    Calculate the maximum sum of values collected on two disjoint paths
    (sharing cells counts only once) from the top-left to the bottom-right
    of an N x N grid.
    """
    if N <= 0:
        return 0

    # Build grid with 1-indexing; default values are 0
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for triple in grid_values:
        if len(triple) != 3:
            continue
        x, y, val = triple
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # Dynamic programming: dp[i1][i2] is the best value when path1 is at (i1, j1)
    # and path2 is at (i2, j2) after the same number of steps.
    NEG_INF = float('-inf')
    dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]  # starting cell value (collect only once)

    for steps in range(2, 2 * N + 1):
        newdp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        for i1 in range(1, N + 1):
            j1 = steps - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(1, N + 1):
                j2 = steps - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG_INF
                # Possible previous moves: up or left for each path
                for pi1 in (i1 - 1, i1):
                    for pi2 in (i2 - 1, i2):
                        if pi1 >= 1 and pi2 >= 1:
                            val_prev = dp[pi1][pi2]
                            if val_prev > best:
                                best = val_prev
                if best == NEG_INF:
                    continue
                cell_val = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    cell_val += grid[i2][j2]
                newdp[i1][i2] = best + cell_val
        dp = newdp

    result = dp[N][N]
    return result if result != NEG_INF else 0

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.
    """
    def is_valid(num: int) -> bool:
        s = str(num)
        if len(s) != 3:
            return False
        if '0' in s:
            return False
        return len(set(s)) == 3

    results = []
    for n in range(123, 334):  # Upper bound exclusive (333 max)
        if not is_valid(n):
            continue
        m1 = 2 * n
        m2 = 3 * n
        if m1 > 999 or m2 > 999:
            continue
        if is_valid(m1) and is_valid(m2):
            results.append((n, m1, m2))
    return results

