    # Pre‑compute for each potential aisle which pairs it separates
    row_map = [set() for _ in range(M + 1)]  # index 1..M-1 valid
    col_map = [set() for _ in range(N + 1)]  # index 1..N-1 valid
    for i, ((x1, y1), (x2, y2)) in enumerate(pairs):
        # Rows
        if x1 != x2:
            lower = min(x1, x2)
            upper = max(x1, x2)
            # all r such that lower <= r < upper
            for r in range(lower, upper):
                row_map[r].add(i)
        # Columns
        if y1 != y2:
            lower = min(y1, y2)
            upper = max(y1, y2)
            for c in range(lower, upper):
                col_map[c].add(i)

    selected_rows = set()
    selected_cols = set()
    separated_pairs = set()

    # Helper functions to compute gain
    def row_gain(r):
        return len(row_map[r] - separated_pairs)

