            for r in range(1, M):
                if r in selected_rows:
                    continue
                g = row_gain(r)
                if g > best_gain or (g == best_gain and best_is_row is not False and (g != -1)):
                    best_gain = g
                    best_is_row = True
                    best_index = r
        # Evaluate columns
        if len(selected_cols) < L:
            for c in range(1, N):
                if c in selected_cols:
                    continue
                g = col_gain(c)
                if g > best_gain or (g == best_gain and best_is_row is True):  # rows have priority on tie
                    best_gain = g
                    best_is_row = False
                    best_index = c

        # If no gain and still need aisles, pick smallest unused index
        if best_index is None:
            # choose row or column arbitrarily
            if len(selected_rows) < K:
                for r in range(1, M):
                    if r not in selected_rows:
                        best_index = r
                        best_is_row = True
                        break
            if best_index is None and len(selected_cols) < L:
                for c in range(1, N):
                    if c not in selected_cols:
                        best_index = c
                        best_is_row = False
                        break

        if best_is_row:
