def process_random_numbers(numbers: List[int]) -> Tuple[int, List[int]]:
    """
    Remove duplicate integers from the input list and return the sorted unique numbers.

    The function first converts the input list of numbers into a set to remove any duplicates,
    then sorts the resulting set of unique numbers. It returns a tuple containing the count
    of unique numbers and a list of these unique numbers in ascending order.
    """
    try:
        if numbers is None:
            raise TypeError("Input cannot be None")
        # Accept any iterable (list, tuple, set, etc.) but enforce on each element
        if not hasattr(numbers, "__iter__"):
            raise TypeError("Input must be an iterable of integers")
        # Validate each element is an int
        for idx, val in enumerate(numbers):
            if not isinstance(val, int):
                raise ValueError(f"Element at index {idx} is not an int: {val!r}")
        unique_set = set(numbers)
        sorted_list = sorted(unique_set)
        return len(sorted_list), sorted_list
    except Exception as e:
        # Reraise exception with context for debugging
        raise e from None

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if n < 0:
        raise ValueError("n must be non-negative")
    if len(coeffs) != n + 1:
        raise ValueError("coeffs length must be n + 1")
    terms = []
    first_term = True
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        sign = ""
        abscoeff = abs(coeff)
        if first_term:
            if coeff < 0:
                sign = "-"
        else:
            sign = "+" if coeff > 0 else "-"
        if degree == 0:
            term_body = str(abscoeff)
        else:
            var_part = "x" if degree == 1 else f"x^{degree}"
            if abscoeff == 1:
                term_body = var_part
            else:
                term_body = f"{abscoeff}{var_part}"
        terms.append(sign + term_body)
        first_term = False
    if not terms:
        return "0"
    return "".join(terms)

def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (list[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    if n < 0:
        raise ValueError("Degree must be non-negative")
    if len(coeffs) != n + 1:
        raise ValueError("Coefficient list length must be degree + 1")
    terms = []
    first_term = True
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        # Determine sign
        if first_term:
            sign = "-" if coeff < 0 else ""
        else:
            sign = "-" if coeff < 0 else "+"
        abs_coeff = abs(coeff)
        # Determine coefficient representation
        if degree == 0 or abs_coeff != 1:
            coeff_str = str(abs_coeff)
        else:
            coeff_str = ""
        # Determine variable part
        if degree == 0:
            var_str = ""
        elif degree == 1:
            var_str = "x"
        else:
            var_str = f"x^{degree}"
        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)
        first_term = False
    if not terms:
        return "0"
    return "".join(terms)

def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    """
    Selects and determines the interview score cutoff and the list of applicants who qualify for the interview process.

    The function sorts the applicants based on their test scores in descending order. If multiple applicants have the
    same score, they are then sorted by their registration number in ascending order. The interview score cutoff 
    is calculated based on 150% of the planned number of recruits, rounded down. All applicants with scores equal 
    to or higher than the cutoff are considered qualified for the interview.

    Args:
        n (int): The total number of applicants.
        m (int): The planned number of volunteers to be recruited.
        applicants (List[Tuple[int, int]]): A list of tuples where each tuple contains the registration number
                                            and test score of an applicant.

    Returns:
        Tuple[int, List[Tuple[int, int]]]: A tuple containing the interview score cutoff and a list of tuples,
                                            each of which includes the registration number and test score of 
                                            qualified applicants.
    """
    try:
        # Basic type checks
        if not isinstance(n, int) or not isinstance(m, int):
            raise TypeError("n and m must be integers")
        if not isinstance(applicants, list):
            raise TypeError("applicants must be a list of tuples")
        for item in applicants:
            if not (isinstance(item, tuple) and len(item) == 2):
                raise TypeError("each applicant must be a tuple of (registration_number, score)")
            if not (isinstance(item[0], int) and isinstance(item[1], int)):
                raise TypeError("registration_number and score must be integers")

        # If no applicants, return 0 cutoff and empty list
        if not applicants:
            return (0, [])

        # Sort applicants by score descending, then registration number ascending
        sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

        # Calculate cutoff index: 150% of m, rounded down
        cutoff_count = (m * 3) // 2  # floor of 1.5 * m

        # Determine cutoff score
        if cutoff_count <= 0:
            cutoff_score = 0
        elif cutoff_count > len(sorted_applicants):
            cutoff_score = sorted_applicants[-1][1]  # lowest score
        else:
            cutoff_score = sorted_applicants[cutoff_count - 1][1]

        # Select qualified applicants (score >= cutoff_score)
        qualified = [app for app in sorted_applicants if app[1] >= cutoff_score]

        return (cutoff_score, qualified)

    except Exception:
        # In case of any unexpected error, return default safe values
        return (0, [])

