def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.

    The function relies on the fact that P = x0 * a and Q = x0 * b for
    some coprime positive integers a, b with a * b = y0 / x0.
    """
    # Basic validation
    if not isinstance(x0, int) or not isinstance(y0, int):
        raise TypeError("x0 and y0 must be integers")
    if x0 <= 0 or y0 <= 0:
        raise ValueError("x0 and y0 must be positive integers")

    # y0 must be a multiple of x0, otherwise no solutions
    if y0 % x0 != 0:
        return 0

    k = y0 // x0

    # Euclidean algorithm for gcd
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    limit = int(k ** 0.5)
    count = 0

    for a in range(1, limit + 1):
        if k % a == 0:
            b = k // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.

    Parameters:
    A (str): The initial string to be transformed.
    B (str): The target string to be achieved.
    rules (list of tuples): A list of transformation rules, where each rule is a tuple
                            containing the source substring (to be replaced) and the
                            target substring (to replace with).

    Returns:
    Union[int, str]: The minimum number of transformation steps if possible, otherwise "NO ANSWER!".
    """
    try:
        # Basic input validation
        if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
            return "NO ANSWER!"

        if A == B:
            return 0

        from collections import deque

        q = deque([(A, 0)])
        visited = {A}
        max_steps = 10

        while q:
            cur, step = q.popleft()

            # Stop expanding if reached maximum allowed steps
            if step >= max_steps:
                continue

            for src, dst in rules:
                if not isinstance(src, str) or not isinstance(dst, str) or src == "":
                    continue  # skip malformed rules

                start = 0
                while True:
                    idx = cur.find(src, start)
                    if idx == -1:
                        break

                    new_str = cur[:idx] + dst + cur[idx + len(src) :]
                    if new_str == B:
                        return step + 1

                    if new_str not in visited:
                        visited.add(new_str)
                        q.append((new_str, step + 1))

                    # Move one character ahead to allow overlapping matches
                    start = idx + 1

        return "NO ANSWER!"
    except Exception:
        return "NO ANSWER!"

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses Breadth-First Search (BFS) up to a maximum of 10 steps.
    Returns the minimum number of steps if possible, otherwise "NO ANSWER!".
    """
    # Basic input validation
    if not isinstance(A, str) or not isinstance(B, str):
        raise ValueError("A and B must be strings.")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples.")
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule) == 2):
            raise ValueError("Each rule must be a tuple of (source, target).")

    # Trivial case: already equal
    if A == B:
        return 0

    # BFS initialization
    from collections import deque
    queue = deque()
    queue.append((A, 0))
    visited = {A: 0}
    MAX_STEPS = 10

    while queue:
        current, steps = queue.popleft()
        if steps >= MAX_STEPS:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                # Replace at idx
                new_str = current[:idx] + tgt + current[idx + len(src):]
                new_steps = steps + 1
                if new_str == B:
                    return new_steps
                # Avoid revisiting at equal or better depth
                if new_str not in visited or visited[new_str] > new_steps:
                    visited[new_str] = new_steps
                    queue.append((new_str, new_steps))
                start = idx + 1  # move past this index for next search

    return "NO ANSWER!"

def generate_numbers(n, rules):
    """
    Generate all unique numbers reachable from the integer `n` by repeatedly applying
    single‑digit transformation rules. Each rule is a tuple (x, y) meaning that a
    digit with value `x` can be changed to a digit `y`. All transformations are
    explored via a breadth‑first search and duplicate numbers are avoided.

    Args:
        n (int): The original integer (must be non‑negative).
        rules (list of tuple): List of transformation rules `(x, y)` where `x` and
                               `y` are integers in 0..9.

    Returns:
        int: The count of unique integers obtainable from `n` (including `n` itself).

    Raises:
        TypeError: If `n` is not an int or rules is not a list of 2‑int tuples.
        ValueError: If `n` is negative or any rule contains invalid digits.
    """
    # Basic type and value checks
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non‑negative")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples")
    for rule in rules:
        if (
            not isinstance(rule, tuple)
            or len(rule) != 2
            or not all(isinstance(d, int) for d in rule)
        ):
            raise TypeError("each rule must be a tuple of two integers")
        if not (0 <= rule[0] <= 9 and 0 <= rule[1] <= 9):
            raise ValueError("digits in rules must be between 0 and 9 inclusive")

    # Preprocess rules into a dictionary for quick lookup: digit -> list of new digits
    rule_map = {}
    for x, y in rules:
        rule_map.setdefault(x, []).append(y)

    start_str = str(n)
    visited_numbers = {n}
    queue = [start_str]  # list used as simple queue (popleft via index)

    while queue:
        current = queue.pop(0)
        for idx, ch in enumerate(current):
            digit = int(ch)
            if digit not in rule_map:
                continue
            for new_digit in rule_map[digit]:
                new_num_str = current[:idx] + str(new_digit) + current[idx + 1 :]
                new_num = int(new_num_str)
                if new_num not in visited_numbers:
                    visited_numbers.add(new_num)
                    queue.append(new_num_str)

    return len(visited_numbers)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to evaluate a single statement
    def _evaluate(statement: str, speaker: str) -> bool | None:
        stmt = statement.strip()
        if not stmt:
            return None
        lower = stmt.lower()
        # Skip statements that mention any day of the week
        for day in days_of_week:
            if day.lower() in lower:
                return None

        # Determine if the statement asserts guilt or innocence
        neg = "not guilty" in lower
        if neg:
            guilty = False
        else:
            guilty = "guilty" in lower

        # Identify the person being referred to
        if lower.startswith("i am"):
            target = speaker
        else:
            # Look for a pattern like "<NAME> is guilty" or "<NAME> is not guilty"
            parts = stmt.split()
            if "is" not in parts:
                return None
            is_index = parts.index("is")
            # The name is the word before "is"
            target = parts[is_index - 1].strip(".,;:!?")
        # Determine truth value of the statement
        if target == scenario:
            return guilty
        else:
            return not guilty

    for speaker, stmts in statements.items():
        for stmt in stmts:
            truth = _evaluate(stmt, speaker)
            if truth is None:
                continue  # Skip irrelevant or malformed statements
            is_liar = speaker in liar_count
            if is_liar and truth:
                # Liars should not tell a true statement
                return False
            if not is_liar and not truth:
                # Non-liars should not tell a false statement
                return False
    return True

