        days_of_week (set): A set of strings representing the days of the week.

    Returns:
        bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to determine if a statement is about the day of the week
    def _is_day_statement(st: str) -> bool:
        upper = st.upper()
        for day in days_of_week:
            if day.upper() in upper:
                return True
        return False

    # Helper to evaluate truth of a criminal related statement
    def _evaluate_statement(st: str, speaker: str, scenario: str):
        stmt = st.lower().replace('.', '').replace(',', '').replace('?', '').replace('!', '')
        # Simple patterns
        if "i am guilty" in stmt:
            return scenario == speaker
        if "i am not guilty" in stmt:
            return scenario != speaker
        # Patterns like "NAME is guilty"/"NAME is not guilty"
        parts = stmt.split()
        if len(parts) >= 3 and parts[1] == 'is':
            # Normalize name (strip punctuation)
            name = parts[0].replace('the', '').strip().upper()
            if parts[2] == 'guilty':
                return scenario == name
            if parts[2] == 'not' and len(parts) >= 4 and parts[3] == 'guilty':
                return scenario != name
        # Unknown pattern -> cannot be evaluated for consistency
        return None

    scenario_title = scenario.upper()
    for speaker, stmts in statements.items():
        speaker_title = speaker.upper()
        for st in stmts:
            if _is_day_statement(st):
                continue
            truth_val = _evaluate_statement(st, speaker_title, scenario_title)
            if truth_val is None:
                continue  # Cannot evaluate, skip
            is_liar = speaker_title in {name.upper() for name in liar_count}
            if is_liar and truth_val:
                return False
            if not is_liar and not truth_val:
                return False
    return True

def remaining_trees_after_clearing(l: int, areas: list[tuple[int, int]]) -> int:
    """
    Calculates the number of trees remaining on a road of length `l` after
    specific integer-interval segments have been cleared.

    Args:
        l (int): The length of the road (number of unit intervals).
        areas (list[tuple[int, int]]): List of (start, end) pairs, where
            each pair represents a cleared segment. The pair is inclusive
            on start and exclusive on end when calculating tree removal.

    Returns:
        int: The number of trees remaining after the cleared segments.
    """
    try:
        if l <= 0:
            return 0

        # Prepare a list of valid, sorted, non-overlapping intervals
        intervals = []

        for start, end in areas:
            # Ensure start <= end
            if start > end:
                start, end = end, start

            # Clamp to road bounds
            start = max(start, 0)
            end = min(end, l)

            if start < end:
                intervals.append((start, end))

        if not intervals:
            return l

        intervals.sort()

        merged = []
        for s, e in intervals:
            if not merged or s > merged[-1][1]:
                merged.append([s, e])
            else:
                merged[-1][1] = max(merged[-1][1], e)

        cleared = sum(e - s for s, e in merged)
        remaining = l - cleared
        return max(remaining, 0)

    except Exception:
        return 0

def max_herb_value(T: int, M: int, herbs: list) -> int:
    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.

    This function solves a variation of the 0/1 knapsack problem where the goal is to maximize
    the total value of herbs picked without exceeding the time limit. Each herb can be picked
    at most once and has an associated time cost and value.

    Args:
        T (int): The total time available for picking herbs.
        M (int): The number of different herbs in the cave.
        herbs (List[Tuple[int, int]]): A list of tuples, where each tuple contains two integers
            representing the time required to pick the herb and the herb's value, respectively.

    Returns:
        int: The maximum total value of herbs that can be picked within the time limit.
    """
    try:
        if not isinstance(T, int) or not isinstance(M, int):
            return 0
        if T < 0 or M < 0:
            return 0
        if not isinstance(herbs, list):
            return 0
        # Filter valid herb entries
        valid_herbs = []
        for item in herbs:
            if (isinstance(item, (tuple, list)) and len(item) == 2 and
                isinstance(item[0], int) and isinstance(item[1], int)):
                time_cost, value = item
                if time_cost >= 0 and value >= 0:
                    valid_herbs.append((time_cost, value))
        if not valid_herbs or T == 0:
            return 0

        dp = [0] * (T + 1)
        for time_cost, value in valid_herbs:
            if time_cost > T:
                continue
            for t in range(T, time_cost - 1, -1):
                new_val = dp[t - time_cost] + value
                if new_val > dp[t]:
                    dp[t] = new_val
        return max(dp)
    except Exception:
        return 0

def min_remaining_space(V: int, n: int, volumes: list) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.

    This function uses a dynamic programming approach to determine the maximum volume that can be occupied
    in the box by any subset of the given items. It then returns the difference between the box's total capacity
    and this maximum occupied volume, which is the minimum remaining space.

    Args:
    - V (int): The total capacity of the box.
    - n (int): The number of items to consider for packing into the box.
    - volumes (List[int]): A list of the volumes of the n items.

    Returns:
    - int: The minimum remaining space in the box after fitting the items.
    """
    # Basic validation and edge cases
    try:
        if V < 0:
            return 0
        if n <= 0 or not volumes:
            return max(0, V)
        # In case the provided list is shorter/longer than n, we only use the first n valid integers
        volumes_to_use = [v for v in volumes[:n] if isinstance(v, int) and v >= 0]
        if not volumes_to_use:
            return max(0, V)
    except Exception:
        return max(0, V)

    # DP array: dp[s] is True if a subset of items can achieve total volume s
    dp = [False] * (V + 1)
    dp[0] = True
    best_sum = 0

    for vol in volumes_to_use:
        if vol > V:
            continue
        # Traverse backwards to avoid reusing the same item
        for s in range(V, vol - 1, -1):
            if dp[s - vol]:
                dp[s] = True
                if s > best_sum:
                    best_sum = s
                    # Early exit if perfect fit found
                    if best_sum == V:
                        return 0

    # In case the best sum was not found inside the loop, recompute in case dp[best] is True
    for s in range(V, -1, -1):
        if dp[s]:
            best_sum = s
            break

    remaining = V - best_sum
    return remaining if remaining >= 0 else 0

def min_remaining_space(V: int, n: int, volumes: list[int]) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.
    Parameters:
    - V (int): The total capacity of the box.
    - n (int): The number of items to consider for packing into the box.
    - volumes (list[int]): A list of the volumes of the n items.
    Returns:
    - int: The minimum remaining space in the box after fitting the items.
    """
    # Handle invalid capacity or empty volume list
    if V <= 0 or not volumes:
        return max(V, 0)

    # Ensure n does not exceed available items
    n = min(n, len(volumes))
    items = volumes[:n]

    # Quick check: if box can hold everything
    total = sum(items)
    if total <= V:
        return V - total

    # If any single item exactly fits the capacity
    if any(item == V for item in items):
        return 0

    # 0/1 knapsack dynamic programming using a boolean array
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in items:
        if vol < 0:
            continue  # skip negative volumes
        if vol > V:
            continue
        for j in range(V, vol - 1, -1):
            if dp[j - vol]:
                dp[j] = True

    # Find the largest achievable volume <= V
    for used in range(V, -1, -1):
        if dp[used]:
            return V - used

    # Fallback (should not reach here)
    return V

def min_remaining_space(V: int, n: int, volumes: list) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.

    This function uses a dynamic programming approach to determine the maximum volume that can be occupied
    in the box by any subset of the given items. It then returns the difference between the box's total
    capacity and this maximum occupied volume, which is the minimum remaining space.

    Args:
        V (int): The total capacity of the box.
        n (int): The number of items to consider for packing into the box.
        volumes (list[int]): A list of the volumes of the n items.

    Returns:
        int: The minimum remaining space in the box after fitting the items.
    """
    # Ensure input validity
    try:
        if not isinstance(V, int) or V < 0:
            return 0
        if not isinstance(n, int) or n <= 0:
            return V
        if not isinstance(volumes, (list, tuple)):
            return V
    except Exception:
        return V

    # Use at most first n items
    items = [v for v in volumes[:n] if isinstance(v, int) and v > 0 and v <= V]
    if not items:
        return V

    # dp[i] == True if volume i is achievable
    dp = [False] * (V + 1)
    dp[0] = True

    for vol in items:
        for cap in range(V, vol - 1, -1):
            if dp[cap - vol]:
                dp[cap] = True

    # Find maximum achievable volume <= V
    for used in range(V, -1, -1):
        if dp[used]:
            return V - used

    # Should never reach here; return original capacity as fallback
    return V

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    if len(heights) == 0:
        return 0
    if not all(isinstance(h, int) for h in heights):
        raise TypeError("all elements in heights must be integers")

    n = len(heights)
    if n <= 1:
        return 0

    inc = [1] * n  # LIS ending at i
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i]:
                inc[i] = max(inc[i], inc[j] + 1)

    dec = [1] * n  # LDS starting at i
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i]:
                dec[i] = max(dec[i], dec[j] + 1)

    max_len = 0
    for i in range(n):
        # peak counted twice, so subtract 1
        bitonic_len = inc[i] + dec[i] - 1
        if bitonic_len > max_len:
            max_len = bitonic_len

    return n - max_len

