def sort_students(student_scores):
    """Sort a list of students based on score criteria.

    Sorts first by total score descending, then by Chinese score descending,
    and finally by student number ascending if needed.

    Args:
        student_scores (list): A list of tuples, each defined as
                               (student_number, total_score, chinese_score).

    Returns:
        list: Sorted list of tuples according to the rules.

    Raises:
        TypeError: If `student_scores` is not a list.
        ValueError: If an element is not a tuple of three numeric values.
    """
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list")

    # Validate each item; store a copy with proper types for sorting
    validated = []
    for idx, item in enumerate(student_scores):
        if not isinstance(item, tuple):
            raise ValueError(f"Element at index {idx} is not a tuple")
        if len(item) != 3:
            raise ValueError(f"Element at index {idx} does not contain 3 values")
        sn, total, chinese = item
        try:
            sn_int = int(sn)
        except Exception:
            raise ValueError(f"Student number at index {idx} must be convertible to int")
        try:
            total_num = float(total)
        except Exception:
            raise ValueError(f"Total score at index {idx} must be numeric")
        try:
            chinese_num = float(chinese)
        except Exception:
            raise ValueError(f"Chinese score at index {idx} must be numeric")
        validated.append((sn_int, total_num, chinese_num))

    # Perform sorting
    try:
        sorted_list = sorted(
            validated,
            key=lambda t: (-t[1], -t[2], t[0])
        )
    except Exception as e:
        raise ValueError(f"Error during sorting: {e}") from e

    return sorted_list
